// orders · общие помощники для тестов с собственным товаром «QA-AUTO-…» и заказом клиента «test» (buyer).
// Общий товар «מצית קליפט» на staging почти без остатка (21.10 — 1 шт.), поэтому тесты создают свой товар с остатком «ללא מקום».
// Заказы неудаляемы → хвосты отклоняются (rejectIfPending); товар удаляется (остаток «ללא מקום» удаляется обычным окном, решение 05.10).
import { test, expect, Page, Browser } from '@playwright/test';
import * as path from 'path';

export const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);

// ---------- товар ----------
const qtyBtn = (page: Page, p: string) => page.getByRole('button', { name: `קליטת מלאי — ${p}`, exact: true });
const catalogRow = (page: Page, p: string) => qtyBtn(page, p).locator('xpath=ancestor::*[.//button[@aria-label="פעולות"]][1]');

export async function findProduct(page: Page, p: string) {
  await page.goto('/catalog');
  await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(p);
  await expect(qtyBtn(page, p).or(page.getByText('לא נמצאו מוצרים התואמים לסינון'))).toBeVisible({ timeout: 20_000 });
  return (await qtyBtn(page, p).count()) > 0;
}

/** Создаёт товар (цена basePrice), принимает qty шт. «ללא מקום»; возвращает id товара. */
export async function createStockedProduct(page: Page, p: string, sku: string, basePrice: number, qty: number): Promise<string> {
  await page.goto('/catalog/new');
  await expect(page.getByRole('heading', { level: 1, name: 'מוצר חדש' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('textbox', { name: /שם מוצר/ }).fill(p);
  await page.getByRole('textbox', { name: /מק"ט/ }).fill(sku);
  await page.getByRole('spinbutton', { name: 'מחיר בסיס' }).fill(String(basePrice));
  await page.getByRole('button', { name: 'שמירה', exact: true }).click();
  await expect(page.getByText('נוסף לקטלוג.')).toBeVisible({ timeout: 15_000 });

  await findProduct(page, p);
  await qtyBtn(page, p).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'הוספת פריט למלאי' })).toBeVisible();
  await dlg.getByRole('spinbutton', { name: 'כמות', exact: true }).fill(String(qty));
  await dlg.getByRole('button', { name: 'הוספה' }).click();
  await expect(dlg).toHaveCount(0, { timeout: 15_000 });
  await expect(qtyBtn(page, p)).toHaveText(String(qty), { timeout: 15_000 });

  await page.getByRole('button', { name: p, exact: true }).first().click();
  await expect(page).toHaveURL(/\/catalog\/[0-9a-f-]{36}\/edit$/, { timeout: 20_000 });
  const id = page.url().match(/\/catalog\/([0-9a-f-]{36})\/edit$/)![1];
  await page.getByRole('button', { name: 'ביטול', exact: true }).click();
  return id;
}

/** Создаёт товар без остатка (цена basePrice) — для сценариев «אזל מהמלאי». */
export async function createProduct(page: Page, p: string, sku: string, basePrice: number) {
  await page.goto('/catalog/new');
  await expect(page.getByRole('heading', { level: 1, name: 'מוצר חדש' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('textbox', { name: /שם מוצר/ }).fill(p);
  await page.getByRole('textbox', { name: /מק"ט/ }).fill(sku);
  await page.getByRole('spinbutton', { name: 'מחיר בסיס' }).fill(String(basePrice));
  await page.getByRole('button', { name: 'שמירה', exact: true }).click();
  await expect(page.getByText('נוסף לקטלוג.')).toBeVisible({ timeout: 15_000 });
}

export async function deleteProduct(page: Page, p: string) {
  if (!(await findProduct(page, p))) return;
  await catalogRow(page, p).getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: /^מחיקה/ }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'מחיקת מוצר' })).toBeVisible({ timeout: 20_000 });
  await dlg.getByRole('button', { name: 'מחיקה', exact: true }).click();
  await expect(page.getByText(/הוסר מהקטלוג|נמחק\./).first()).toBeVisible({ timeout: 15_000 });
}

// ---------- корзина и заказ buyer ----------
export async function emptyCart(page: Page) {
  await page.goto('/shop/cart');
  await expect(page.getByRole('heading', { name: 'העגלה שלי' })).toBeVisible({ timeout: 30_000 });
  const remove = page.getByRole('button', { name: /^הסרה מהעגלה/ });
  await expect(remove.first().or(page.getByText('העגלה ריקה'))).toBeVisible({ timeout: 20_000 });
  for (let n = await remove.count(); n > 0; n = await remove.count()) {
    await remove.first().click();
    await expect(remove).toHaveCount(n - 1, { timeout: 15_000 });
  }
  await expect(page.getByText('העגלה ריקה')).toBeVisible();
}

/** Заказ клиента «test»: товары [{id, name, qty}], заметка note. Возвращает номер заказа. */
export async function placeOrder(page: Page, items: { id: string; name: string; qty: number }[], note: string): Promise<string> {
  await emptyCart(page);
  for (const it of items) {
    await page.goto(`/shop/p/${it.id}`);
    const added = page.waitForResponse((r) => r.url().includes('cart_set_item'));
    await page.getByRole('button', { name: /^הוסף לעגלה/ }).click();
    await added;
  }
  await page.goto('/shop/cart');
  for (const it of items) {
    const qty = page.getByText(it.name, { exact: true });
    await expect(qty).toBeVisible({ timeout: 20_000 });
    for (let i = 1; i < it.qty; i++) {
      const resp = page.waitForResponse((r) => r.url().includes('cart_set_item'));
      await page.getByRole('button', { name: `הוספת יחידה — ${it.name}` }).click();
      await resp;
    }
  }
  await page.getByRole('button', { name: 'המשך לביצוע הזמנה' }).click();
  await page.getByRole('textbox', { name: 'הערות להזמנה' }).fill(note);
  await page.getByRole('button', { name: 'שליחת הזמנה' }).click();
  await expect(page.getByRole('heading', { name: 'ההזמנה נקלטה!' })).toBeVisible({ timeout: 30_000 });
  return (await page.getByText(/^הזמנה\s*#\d+/).first().innerText()).match(/#(\d+)/)![1];
}

export async function buyerPlaceOrder(browser: Browser, items: { id: string; name: string; qty: number }[], note: string) {
  const ctx = await browser.newContext({ storageState: auth('buyer'), locale: 'he-IL' });
  try {
    return await placeOrder(await ctx.newPage(), items, note);
  } finally {
    await ctx.close();
  }
}

// ---------- карточка заказа (admin) ----------
export const header = (page: Page) => page.getByRole('heading', { level: 1 }).locator('..');

export async function openOrder(page: Page, no: string) {
  await page.goto('/orders');
  await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
  const row = page.getByRole('button', { name: new RegExp(`^#${no} `) });
  await expect(row).toBeVisible({ timeout: 30_000 });
  await row.click();
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${no}` })).toBeVisible({ timeout: 30_000 });
}

/** Отклоняет заказ, если он ещё «ממתינה לאישור» (есть «דחייה»). */
export async function rejectIfPending(page: Page, no: string, reason = 'QA-AUTO cleanup') {
  await openOrder(page, no);
  const btn = page.getByRole('button', { name: 'דחייה' });
  if (!(await btn.count())) return false;
  await btn.click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: `דחיית הזמנה #${no}` })).toBeVisible();
  await dlg.getByRole('textbox', { name: 'סיבת הדחייה *' }).fill(reason);
  await dlg.getByRole('button', { name: 'דחה הזמנה' }).click();
  await expect(header(page)).toContainText('נדחתה', { timeout: 20_000 });
  return true;
}

/** Уборка под admin в отдельном окне: отклонить заказы, удалить товары. Ошибки одной операции не мешают остальным. */
export async function cleanup(browser: Browser, orders: (string | undefined)[], products: string[]) {
  const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  const errors: string[] = [];
  for (const no of orders) {
    if (!no) continue;
    try { await rejectIfPending(page, no); } catch (e) { errors.push(`reject #${no}: ${(e as Error).message.split('\n')[0]}`); }
  }
  for (const p of products) {
    try { await deleteProduct(page, p); } catch (e) { errors.push(`delete ${p}: ${(e as Error).message.split('\n')[0]}`); }
  }
  await ctx.close();
  if (errors.length) test.info().annotations.push({ type: 'cleanup', description: errors.join(' | ') });
}
